import { useEffect, useRef, useState } from 'react';
import { SearchCheck } from 'lucide-react';
import { sourcingIsActive, type Services, type SourcingReview, type SourcingRun } from '../services';
import ScoutReview from './ScoutReview';

const demoBrief = 'Find 1 kHz robot collision and intentional contact time-series torque data from https://github.com/zhang-zengjie/robot-raw-collision-signals';
const errorText = (error: unknown) => error instanceof Error ? error.message : 'The request failed.';
type Intent = { brief: string; key: string };

export default function DatasetScout({ services, onUseSource }: { services: Services; onUseSource: (url: string) => void }) {
  const [brief, setBrief] = useState(demoBrief);
  const [resumeId, setResumeId] = useState('');
  const [runId, setRunId] = useState('');
  const [pollRevision, setPollRevision] = useState(0);
  const [run, setRun] = useState<SourcingRun | null>(null);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [sourceReady, setSourceReady] = useState(false);
  const intent = useRef<Intent | null>(null);

  useEffect(() => {
    if (!runId || !services.connected) return;
    let alive = true;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const poll = async () => {
      try {
        const next = await services.getSourcingRun(runId);
        if (!alive) return;
        setRun(next); setError('');
        if (sourcingIsActive(next.status)) timer = setTimeout(poll, 1500);
      } catch (reason) { if (alive) setError(`Could not load sourcing run: ${errorText(reason)}`); }
    };
    void poll();
    return () => { alive = false; clearTimeout(timer); };
  }, [services, runId, pollRevision]);

  async function start() {
    const normalized = brief.trim();
    if (normalized.length < 20) { setError('Describe the dataset need in at least 20 characters.'); return; }
    setBusy('start'); setError(''); setRun(null); setSourceReady(false);
    try {
      if (!intent.current || intent.current.brief !== normalized) intent.current = { brief: normalized, key: crypto.randomUUID() };
      const accepted = await services.startSourcingRun({ brief: normalized }, intent.current.key);
      intent.current = null;
      setRunId(accepted.runId); setResumeId(accepted.runId); setPollRevision(value => value + 1);
    } catch (reason) { setError(`Could not start evidence review: ${errorText(reason)}`); }
    finally { setBusy(''); }
  }

  async function review(reviewRequest: SourcingReview) {
    if (!run) return;
    setBusy(reviewRequest.decision); setError('');
    try {
      const next = await services.reviewSourcingRun(run.runId, reviewRequest);
      if (reviewRequest.decision === 'APPROVE') next.manifest = await services.getSourcingManifest(run.runId);
      setRun(next);
    } catch (reason) { setError(`Could not apply reviewer decision: ${errorText(reason)}`); }
    finally { setBusy(''); }
  }

  return <section className="workspace-section dataset-scout" aria-labelledby="scout-title">
    <div className="section-heading"><div><p className="eyebrow">Agentic sourcing</p><h2 id="scout-title">Evidence-complete dataset scout</h2><p>Search bounded hypotheses, verify native sources, and review a deterministic recommendation before ingestion.</p></div><SearchCheck size={20} aria-hidden="true" /></div>
    {!services.connected && <p className="status-note">Configure the team API to run or resume dataset research.</p>}
    <label htmlFor="sourcing-brief">Research brief</label>
    <textarea id="sourcing-brief" rows={3} value={brief} onChange={event => { setBrief(event.target.value); intent.current = null; }} disabled={!services.connected || Boolean(busy)} />
    <div className="scout-actions"><button className="btn btn-primary" type="button" disabled={!services.connected || Boolean(busy)} onClick={() => void start()}><SearchCheck size={15} aria-hidden="true" />{busy === 'start' ? 'Starting…' : 'Start evidence review'}</button><form onSubmit={event => { event.preventDefault(); setError(''); setRun(null); setSourceReady(false); setRunId(resumeId.trim()); setPollRevision(value => value + 1); }}><label htmlFor="sourcing-run-id">Resume run</label><input id="sourcing-run-id" value={resumeId} onChange={event => setResumeId(event.target.value)} placeholder="Run ID" disabled={!services.connected || Boolean(busy)} /><button className="btn" disabled={!services.connected || !resumeId.trim() || Boolean(busy)}>Load</button></form></div>
    {error && <p className="error-message" role="alert">{error}</p>}
    {run ? <ScoutReview run={run} busy={busy} onReview={reviewRequest => void review(reviewRequest)} onUseSource={url => { onUseSource(url); setSourceReady(true); }} /> : runId && !error ? <p className="status-note" aria-live="polite">Loading sourcing run…</p> : null}
    {sourceReady && <p className="status-note" role="status">Source URL added to the ingestion form below. Review it before starting ingestion.</p>}
  </section>;
}
        let boundary: number;
        while (!terminal && (boundary = buffer.indexOf('\n\n')) >= 0) {
          dispatch(buffer.slice(0, boundary)); buffer = buffer.slice(boundary + 2);
        }
        if (done) {
          if (!terminal) throw new ApiError('Connection lost before the answer completed.', 0, 'STREAM_DISCONNECTED', true);
          break;
        }
      }
    } finally {
      await reader.cancel().catch(() => undefined);
      reader.releaseLock();
    }
  }
  return {
    connected,
    listDatasets: () => request<Dataset[]>('/datasets'),
    listRecordings: (datasetId: string) => request<Recording[]>(`/datasets/${encodeURIComponent(datasetId)}/recordings`),
    getWindow: async (recordingId: string, startSec: number, endSec: number, channelIds: string[], maxPoints: number) => {
      validateInterval(startSec, endSec); validateChannels(channelIds);
      if (!Number.isInteger(maxPoints) || maxPoints < 1) throw new ApiError('Invalid display point budget.', 0, 'INVALID_WINDOW');
      const query = new URLSearchParams({ startSec: String(startSec), endSec: String(endSec), channelIds: channelIds.join(','), maxPoints: String(maxPoints) });
      return validateWindow(await request<SignalWindow>(`/recordings/${encodeURIComponent(recordingId)}/signals?${query}`));
    },
    getEvents: (recordingId: string) => request<SignalEvent[]>(`/recordings/${encodeURIComponent(recordingId)}/events`),
    listModels: () => connected ? request<ModelProfile[]>('/models') : Promise.resolve(DECLARED_MODELS.map(model => ({ ...model, capabilities: [...model.capabilities] }))),
    searchDatasets: (query: string) => request<DatasetSearchResult[]>(`/datasets/search?${new URLSearchParams({ query })}`),
    startImport: (sourceUrl: string) => request<{ ingestionId: string }>('/ingestions', { method: 'POST', body: JSON.stringify({ sourceUrl }) }),
    getImport: (id: string) => request<ImportJob>(`/ingestions/${encodeURIComponent(id)}`),
    startSourcingRun: async (input: CreateSourcingRun, idempotencyKey: string) => {
      const accepted = await request<unknown>('/sourcing-runs', {
        method: 'POST', headers: { 'Idempotency-Key': idempotencyKey }, body: JSON.stringify(input),
      });
      if (!isRunAccepted(accepted)) throw new ProtocolError('The sourcing response does not match the accepted-run contract.');
      return accepted;
    },
    getSourcingRun: async (runId: string) => {
      const run = await request<unknown>(`/sourcing-runs/${encodeURIComponent(runId)}`);
      if (!isSourcingRun(run)) throw new ProtocolError('The sourcing response does not match the run contract.');
      return run;
    },
    reviewSourcingRun: async (runId: string, review: SourcingReview) => {
      const run = await request<unknown>(`/sourcing-runs/${encodeURIComponent(runId)}/approvals`, {
        method: 'POST', body: JSON.stringify(review),
      });
      if (!isSourcingRun(run)) throw new ProtocolError('The sourcing response does not match the run contract.');
      return run;
    },
    getSourcingReport: (runId: string) => requestText(`/sourcing-runs/${encodeURIComponent(runId)}/report`),
    getSourcingManifest: async (runId: string) => {
      const manifest = await request<unknown>(`/sourcing-runs/${encodeURIComponent(runId)}/manifest`);
      if (!isSourcingManifest(manifest)) throw new ProtocolError('The sourcing response does not match the manifest contract.');
      return manifest;
    },
    startQuery: async (query: QueryRequest, signal?: AbortSignal) => {
      validateInterval(query.window.startSec, query.window.endSec); validateChannels(query.window.channelIds);
      if (!Number.isFinite(query.playheadSec) || query.window.endSec > query.playheadSec) {
        throw new ApiError('The query window cannot extend beyond the playback cursor.', 0, 'INVALID_WINDOW');
      }
      if (!query.question.trim()) throw new ApiError('Enter a question.', 0, 'INVALID_QUERY');
      if (query.mode === 'direct' && !query.modelId) throw new ApiError('Select a model for direct mode.', 0, 'MODEL_REQUIRED');
      return request<{ queryId: string; streamUrl: string }>('/queries', { method: 'POST', body: JSON.stringify(query), signal });
    },
    streamQuery,
    // Aborting a fetch closes transport only. The caller must also invoke this endpoint.
    cancelQuery: (queryId: string) => request<void>(`/queries/${encodeURIComponent(queryId)}`, { method: 'DELETE' }),
from __future__ import annotations

from datetime import UTC, datetime
from enum import StrEnum
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, HttpUrl, model_validator


def to_camel(value: str) -> str:
    head, *tail = value.split("_")
    return head + "".join(part.title() for part in tail)


class WireModel(BaseModel):
    model_config = ConfigDict(
        alias_generator=to_camel,
        populate_by_name=True,
        extra="forbid",
        str_strip_whitespace=True,
    )


class RunStatus(StrEnum):
    QUEUED = "QUEUED"
    PLANNING = "PLANNING"
    DISCOVERING = "DISCOVERING"
    VERIFYING = "VERIFYING"
    ASSESSING = "ASSESSING"
    AWAITING_APPROVAL = "AWAITING_APPROVAL"
    APPROVED = "APPROVED"
    REJECTED = "REJECTED"
    NEEDS_INPUT = "NEEDS_INPUT"
    FAILED = "FAILED"


class RequirementPriority(StrEnum):
    MUST = "MUST"
    SHOULD = "SHOULD"


class RequirementCategory(StrEnum):
    DOMAIN = "DOMAIN"
    TASK_LABELS = "TASK_LABELS"
    SAMPLING_RATE = "SAMPLING_RATE"
    MODALITY = "MODALITY"
    LICENSE = "LICENSE"
    PROVENANCE = "PROVENANCE"
    SCHEMA = "SCHEMA"
    ACQUISITION = "ACQUISITION"
    OTHER = "OTHER"


class VerificationStatus(StrEnum):
    VERIFIED = "VERIFIED"
    MISSING = "MISSING"
    CONFLICTING = "CONFLICTING"
    UNVERIFIED = "UNVERIFIED"


class SourceKind(StrEnum):
    ZENODO = "ZENODO"
    GITHUB = "GITHUB"
    HUGGING_FACE = "HUGGING_FACE"


class SourceRole(StrEnum):
    DISCOVERY_LEAD = "DISCOVERY_LEAD"
    DATASET_ARTIFACT = "DATASET_ARTIFACT"


class HypothesisStatus(StrEnum):
    PLANNED = "PLANNED"
    SEARCHED = "SEARCHED"
    EXHAUSTED = "EXHAUSTED"


class CandidateTier(StrEnum):
    RECOMMEND = "RECOMMEND"
    SHORTLIST = "SHORTLIST"
    REJECT = "REJECT"


class ConfidenceLevel(StrEnum):
    HIGH = "HIGH"
    MEDIUM = "MEDIUM"
    LOW = "LOW"


class ExecutionMode(StrEnum):
    LIVE = "LIVE"
    CACHED = "CACHED"
    PARTIAL = "PARTIAL"


class ApprovalDecision(StrEnum):
    APPROVE = "APPROVE"
    REJECT = "REJECT"


class RefinementOutcomeStatus(StrEnum):
    RECOMMENDATION_CHANGED = "RECOMMENDATION_CHANGED"
    RECOMMENDATION_WITHHELD = "RECOMMENDATION_WITHHELD"
    EVIDENCE_EXPANDED = "EVIDENCE_EXPANDED"
    CANDIDATES_ADDED = "CANDIDATES_ADDED"
    NO_CHANGE = "NO_CHANGE"


class SourcingConstraints(WireModel):
    must_have: list[str] = Field(default_factory=list, max_length=20)
    preferred: list[str] = Field(default_factory=list, max_length=20)
    allowed_licenses: list[str] = Field(default_factory=list, max_length=20)
    max_download_bytes: int = Field(default=25_000_000_000, gt=0, le=1_000_000_000_000)


class CreateSourcingRun(WireModel):
    brief: str = Field(min_length=20, max_length=8_000)
    constraints: SourcingConstraints = Field(default_factory=SourcingConstraints)


class ResearchRequirement(WireModel):
    id: str = Field(pattern=r"^req_[a-z0-9_]{1,48}$")
    label: str = Field(min_length=1, max_length=120)
    description: str = Field(min_length=1, max_length=500)
    priority: RequirementPriority
    category: RequirementCategory
    expected_values: list[str] = Field(default_factory=list, max_length=30)
    status: VerificationStatus = VerificationStatus.UNVERIFIED
    evidence_ids: list[str] = Field(default_factory=list)


class SearchHypothesis(WireModel):
    id: str = Field(pattern=r"^hyp_[a-z0-9_]{1,48}$")
    rationale: str = Field(min_length=1, max_length=500)
    query: str = Field(min_length=3, max_length=400)
    status: HypothesisStatus = HypothesisStatus.PLANNED
    is_gap_query: bool = False


class SearchResult(WireModel):
    title: str = Field(min_length=1, max_length=500)
    url: HttpUrl
    content: str = Field(default="", max_length=8_000)
    score: float = Field(default=0, ge=0, le=1)
    query: str = Field(default="", max_length=400)


class DatasetCandidate(WireModel):
    id: str = Field(pattern=r"^ds_[a-f0-9]{12}$")
    name: str = Field(min_length=1, max_length=500)
    canonical_url: HttpUrl
    source_kind: SourceKind
    description: str = Field(default="", max_length=8_000)
    revision: str | None = Field(default=None, max_length=200)
    related_urls: list[HttpUrl] = Field(default_factory=list, max_length=20)
    source_role: SourceRole = SourceRole.DISCOVERY_LEAD
    discovery_depth: int = Field(default=0, ge=0, le=2)
    discovered_from_candidate_id: str | None = None


class DatasetProfile(WireModel):
    candidate_id: str
    name: str
    canonical_url: HttpUrl
    source_kinds: list[SourceKind]
    revision: str | None = None
    license_id: str | None = None
    file_count: int | None = Field(default=None, ge=0)
    total_size_bytes: int | None = Field(default=None, ge=0)
    file_extensions: list[str] = Field(default_factory=list)
    domains: list[str] = Field(default_factory=list)
    labels: list[str] = Field(default_factory=list)
    sample_rate_hz: float | None = Field(default=None, gt=0)
    channel_count: int | None = Field(default=None, ge=1)
    is_dataset_artifact: bool = False
    dataset_identity_reason: str = Field(
        default="Dataset identity has not been verified",
        max_length=500,
    )
    has_time_series_files: bool = False
    schema_documented: bool = False
    acquisition_feasible: bool = False


class EvidenceRecord(WireModel):
    id: str = Field(pattern=r"^ev_[a-f0-9]{16}$")
    candidate_id: str
    requirement_id: str | None = None
    claim_key: str = Field(min_length=1, max_length=120)
    observed_value: str = Field(min_length=1, max_length=2_000)
    source_url: HttpUrl
    source_kind: SourceKind
    status: VerificationStatus
    precedence: int = Field(ge=0, le=100)
    retrieved_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    note: str | None = Field(default=None, max_length=1_000)


class GateResult(WireModel):
    gate: str = Field(min_length=1, max_length=80)
    passed: bool
    reason: str = Field(min_length=1, max_length=500)
    evidence_ids: list[str] = Field(default_factory=list)


class ScoreBreakdown(WireModel):
    task_fit: int = Field(ge=0, le=35)
    training_readiness: int = Field(ge=0, le=20)
    acquisition_integrity: int = Field(ge=0, le=15)
    provenance_documentation: int = Field(ge=0, le=10)
    integration_readiness: int = Field(ge=0, le=10)
    license_clarity: int = Field(ge=0, le=5)
    evidence_consistency: int = Field(ge=0, le=5)

    @property
    def total(self) -> int:
        return sum(self.model_dump().values())


class CandidateAssessment(WireModel):
    candidate_id: str
    gates: list[GateResult]
    score: ScoreBreakdown
    total_score: int = Field(ge=0, le=100)
    tier: CandidateTier
    evidence_confidence: ConfidenceLevel
    recommendation_confidence: ConfidenceLevel = ConfidenceLevel.LOW
    missing_requirement_ids: list[str] = Field(default_factory=list)
    conflicts: list[str] = Field(default_factory=list)

    @model_validator(mode="after")
    def total_matches_breakdown(self) -> CandidateAssessment:
        if self.total_score != self.score.total:
            raise ValueError("total_score must equal the score breakdown")
        if any(not gate.passed for gate in self.gates) and self.tier is not CandidateTier.REJECT:
            raise ValueError("a candidate with a failed hard gate must be rejected")
        return self


class ApprovalRequest(WireModel):
    decision: ApprovalDecision
    candidate_id: str | None = None
    note: str | None = Field(default=None, max_length=1_000)

    @model_validator(mode="after")
    def approved_candidate_is_required(self) -> ApprovalRequest:
        if self.decision is ApprovalDecision.APPROVE and not self.candidate_id:
            raise ValueError("candidateId is required when approving")
        if self.decision is ApprovalDecision.REJECT and not self.note:
            raise ValueError("note is required when rejecting for refinement")
        return self


class RefinementOutcome(WireModel):
    iteration: int = Field(ge=1, le=2)
    feedback: str = Field(min_length=1, max_length=1_000)
    query: str = Field(min_length=3, max_length=400)
