      <div><dt>Recommendation confidence</dt><dd>{assessment.recommendationConfidence.toLowerCase()}</dd></div>
    </dl>
    <div className="gate-list" aria-label="Hard gate results">{assessment.gates.map(gate => <div key={gate.gate} className={gate.passed ? 'gate-pass' : 'gate-fail'}>{gate.passed ? <Check size={13} /> : <CircleX size={13} />}<span><strong>{gate.gate.replaceAll('_', ' ')}</strong><small>{gate.reason}</small></span></div>)}</div>
    {assessment.conflicts.length > 0 && <div className="scout-warning"><AlertTriangle size={15} aria-hidden="true" /><div><strong>Conflicting evidence retained</strong>{assessment.conflicts.map(item => <p key={item}>{item}</p>)}</div></div>}
  </article>;
}

function Manifest({ manifest, onUseSource }: { manifest: SourcingManifest; onUseSource: (url: string) => void }) {
  return <div className="scout-manifest">
    <div><p className="eyebrow">Approved manifest</p><h3>{manifest.name}</h3></div>
    <dl className="scout-facts"><div><dt>Revision</dt><dd>{manifest.revision ?? 'Source default'}</dd></div><div><dt>Licence</dt><dd>{manifest.licenseId}</dd></div><div><dt>Evidence records</dt><dd>{manifest.evidenceIds.length}</dd></div><div><dt>Approved</dt><dd>{new Date(manifest.approvedAt).toLocaleString()}</dd></div></dl>
    {manifest.limitations.length > 0 && <div><strong>Known limitations</strong><ul>{manifest.limitations.map(item => <li key={item}>{item}</li>)}</ul></div>}
    <button className="btn btn-primary" onClick={() => onUseSource(manifest.canonicalUrl)}>Use source for ingestion</button>
  </div>;
}

export default function ScoutReview({ run, busy, onReview, onUseSource }: Props) {
  const excludedCandidateIds = new Set(run.excludedCandidateIds);
  const eligible = run.assessments.filter(item =>
    candidateIsEligibleForApproval(item, excludedCandidateIds));
  const eligibleKey = eligible.map(item => item.candidateId).join('|');
  const defaultCandidateId = run.approvedCandidateId ?? run.recommendedCandidateId
    ?? eligible[0]?.candidateId ?? '';
  const [selectedCandidateId, setSelectedCandidateId] = useState(defaultCandidateId);
  const [feedback, setFeedback] = useState('');
  useEffect(() => {
    setSelectedCandidateId(current => eligible.some(item => item.candidateId === current)
      ? current : defaultCandidateId);
    setFeedback('');
  }, [defaultCandidateId, eligibleKey, run.reviewIterationsUsed]);
  const candidate = run.candidates.find(item => item.id === selectedCandidateId);
  const profile = run.profiles.find(item => item.candidateId === selectedCandidateId);
  const assessment = run.assessments.find(item => item.candidateId === selectedCandidateId);
  const mandatoryGaps = run.requirements.filter(item => item.priority === 'MUST' && item.status !== 'VERIFIED');
  const hasRefinementSlot = run.reviewIterationsUsed < 2;
  const hasRefinementCredits = run.tavilyCreditsUsed + 2 <= 12;
  const refinementAvailable = hasRefinementSlot && hasRefinementCredits;
  const normalizedFeedback = feedback.trim();

  return <div className="scout-review" aria-live="polite">
    <div className="scout-run-line"><span className={`run-status status-${run.status.toLowerCase()}`}>{run.status.replaceAll('_', ' ')}</span><span>mode: {run.executionMode.toLowerCase()} · {run.tavilyCreditsUsed}/12 Tavily credits · {run.gapQueriesUsed}/2 gap searches</span><span className="mono">{run.runId}</span></div>
    {run.errors.length > 0 && <details className="scout-errors" open={run.status === 'FAILED'}><summary>Source coverage notes ({run.errors.length})</summary><ul>{run.errors.map(error => <li role={run.status === 'FAILED' ? 'alert' : undefined} key={error}>{friendlyRetrievalNote(error, run)}</li>)}</ul></details>}
    {mandatoryGaps.length > 0 && <div className="scout-warning"><AlertTriangle size={15} aria-hidden="true" /><div><strong>{run.status === 'NEEDS_INPUT' ? 'Recommendation withheld' : 'Mandatory evidence gaps'}</strong><ul>{mandatoryGaps.map(gap => <li key={gap.id}>{gap.label} — {gap.status.toLowerCase()}</li>)}</ul></div></div>}
    {candidate && assessment && <CandidateSummary candidate={candidate} profile={profile} assessment={assessment} isRecommendation={selectedCandidateId === run.recommendedCandidateId} />}
    {run.assessments.length > 0 && <DecisionEvidence run={run} candidateId={selectedCandidateId || undefined} />}
    {run.status === 'AWAITING_APPROVAL' && <section className="scout-approval" aria-labelledby="scout-approval-title">
      <div><strong id="scout-approval-title">Human decision required</strong><p>Approve any eligible dataset, or give the scout specific feedback for another bounded search.</p></div>
      <div className="scout-approval-grid">
        <div className="scout-approval-choice">
          <label htmlFor={`approval-candidate-${run.runId}`}>Dataset to approve</label>
          <select id={`approval-candidate-${run.runId}`} value={selectedCandidateId} onChange={event => setSelectedCandidateId(event.target.value)} disabled={Boolean(busy) || eligible.length === 0}>
            {eligible.length === 0 && <option value="">No eligible datasets</option>}
            {eligible.map(item => <option key={item.candidateId} value={item.candidateId}>{run.candidates.find(candidateItem => candidateItem.id === item.candidateId)?.name ?? item.candidateId} — {item.totalScore}/100{item.candidateId === run.recommendedCandidateId ? ' (agent recommendation)' : ''}</option>)}
          </select>
          <small>Only datasets that pass every mandatory gate can be approved.</small>
          <button className="btn btn-primary" disabled={Boolean(busy) || !selectedCandidateId} onClick={() => onReview({ decision: 'APPROVE', candidateId: selectedCandidateId })}>{busy === 'APPROVE' ? 'Approving…' : 'Approve selected dataset'}</button>
        </div>
        <div className="scout-refinement">
          <label htmlFor={`refinement-feedback-${run.runId}`}>What should the scout improve?</label>
          <textarea id={`refinement-feedback-${run.runId}`} rows={3} value={feedback} onChange={event => setFeedback(event.target.value)} placeholder="Example: prioritize datasets with free-motion baselines and CSV files" disabled={Boolean(busy) || !refinementAvailable} />
          <small>{refinementAvailable ? `${run.reviewIterationsUsed}/2 refinement searches used. Feedback is added to the next bounded query.` : hasRefinementSlot ? 'The Tavily credit budget is exhausted; start a new run to continue.' : 'The refinement limit is reached; start a new run to continue.'}</small>
          <button className="btn" disabled={Boolean(busy) || !refinementAvailable || normalizedFeedback.length < 3} onClick={() => onReview({ decision: 'REJECT', candidateId: selectedCandidateId || undefined, note: normalizedFeedback })}>{busy === 'REJECT' ? 'Refining…' : 'Reject and refine'}</button>
        </div>
      </div>
      {run.reviewFeedback.length > 0 && <details className="scout-review-history"><summary>Applied reviewer feedback ({run.reviewFeedback.length})</summary><ol>{run.reviewFeedback.map((item, index) => <li key={`${index}-${item}`}>{item}</li>)}</ol></details>}
    </section>}
    {run.manifest && <Manifest manifest={run.manifest} onUseSource={onUseSource} />}
  </div>;
}
import { ArrowUpRight, Check, CircleX } from 'lucide-react';
import { candidateIsEligibleForApproval, compareCandidateAssessments } from '../services';
import type { EvidenceRecord, RefinementOutcome, SourcingRun } from '../services';

function label(value: string) {
  return value.replaceAll('_', ' ').toLowerCase();
}

function evidenceRecords(run: SourcingRun, ids: string[], candidateId?: string) {
  const expected = new Set(ids);
  return run.evidence.filter(item =>
    expected.has(item.id)
    && (!candidateId || item.candidateId === candidateId),
  );
}

function EvidenceLinks({ records }: { records: EvidenceRecord[] }) {
  if (records.length === 0) return <span className="evidence-empty">No supporting record</span>;
  return <ul className="evidence-links">{records.map(record =>
    <li key={record.id}>
      <a href={record.sourceUrl} target="_blank" rel="noopener noreferrer">
        {record.sourceKind}: {record.observedValue} <ArrowUpRight size={11} aria-hidden="true" />
      </a>
    </li>,
  )}</ul>;
}

function decisionReason(run: SourcingRun, candidateId: string) {
  if (run.excludedCandidateIds.includes(candidateId)) return 'Excluded by reviewer';
  const assessment = run.assessments.find(item => item.candidateId === candidateId);
  if (!assessment) return 'Not assessed';
  const missing = assessment.missingRequirementIds
    .map(id => run.requirements.find(item => item.id === id)?.label ?? id);
  if (missing.length > 0) return `Missing: ${missing.join(', ')}`;
  const failed = assessment.gates.filter(gate => !gate.passed).map(gate => label(gate.gate));
  if (failed.length > 0) return `Failed hard gates: ${failed.join(', ')}`;
  if (assessment.conflicts.length > 0) {
    return `All gates pass; review conflicts in ${assessment.conflicts.map(label).join(', ')}`;
  }
  return 'All mandatory gates passed';
}

function candidateName(run: SourcingRun, candidateId: string | null) {
  if (!candidateId) return 'No eligible dataset';
  return run.candidates.find(item => item.id === candidateId)?.name ?? candidateId;
}

function isDatasetArtifact(run: SourcingRun, candidateId: string) {
  const assessment = run.assessments.find(item => item.candidateId === candidateId);
  const identityGate = assessment?.gates.find(gate => gate.gate === 'dataset_identity');
  if (identityGate) return identityGate.passed;
  const profile = run.profiles.find(item => item.candidateId === candidateId);
  // Runs persisted before dataset-identity evidence was introduced remain readable.
  return profile?.isDatasetArtifact ?? true;
}

function discoveryLeadReason(run: SourcingRun, candidateId: string) {
  const profile = run.profiles.find(item => item.candidateId === candidateId);
  const identityGate = run.assessments
    .find(item => item.candidateId === candidateId)
    ?.gates.find(gate => gate.gate === 'dataset_identity');
  return identityGate?.reason
    ?? profile?.datasetIdentityReason
    ?? 'The native source was not verified as directly publishing dataset files.';
}

function refinementMessage(run: SourcingRun, refinement: RefinementOutcome) {
  const current = candidateName(run, refinement.recommendedCandidateId);
  const candidateCount = refinement.newCandidateIds.length;
  const evidenceCount = refinement.newEvidenceIds.length;
  if (refinement.outcome === 'RECOMMENDATION_WITHHELD') {
    const rejected = candidateName(run, refinement.rejectedCandidateId);
    const excludedCandidateIds = new Set(run.excludedCandidateIds);
    const alternatives = run.assessments.filter(item =>
      candidateIsEligibleForApproval(item, excludedCandidateIds));
    return <><strong>{rejected} was excluded from this run.</strong> {alternatives.length > 0 ? `${alternatives.length} eligible alternative${alternatives.length === 1 ? ' remains' : 's remain'}, but none reached the recommendation threshold.` : 'No eligible alternative was found; the agent recommendation is withheld.'}</>;
  }
  if (refinement.outcome === 'RECOMMENDATION_CHANGED') {
    return <>{candidateName(run, refinement.previousRecommendedCandidateId)} was replaced by <strong>{current}</strong> after adding {candidateCount} candidate{candidateCount === 1 ? '' : 's'} and {evidenceCount} native evidence record{evidenceCount === 1 ? '' : 's'}.</>;
  }
  if (refinement.outcome === 'EVIDENCE_EXPANDED') {
    return <>The scout added {evidenceCount} native evidence record{evidenceCount === 1 ? '' : 's'} across {candidateCount} new candidate{candidateCount === 1 ? '' : 's'}. <strong>{current} remains the recommendation</strong> after rescoring.</>;
  }
  if (refinement.outcome === 'CANDIDATES_ADDED') {
    return <>{candidateCount} new candidate{candidateCount === 1 ? ' was' : 's were'} found, but no new native evidence cleared verification. <strong>{current} remains the recommendation</strong>.</>;
  }
  return <>No new candidates or native evidence were found. <strong>{current} remains the recommendation</strong>; deterministic gates and scores therefore did not change.</>;
}

function RefinementResults({ run }: { run: SourcingRun }) {
  if (run.refinementOutcomes.length === 0) return null;
  return <div className="refinement-results" aria-label="Refinement results">{run.refinementOutcomes.map(refinement =>
    <article className={`refinement-result refinement-${refinement.outcome.toLowerCase()}`} key={refinement.iteration} role="status">
      <strong>Refinement {refinement.iteration}: {refinement.outcome === 'RECOMMENDATION_CHANGED' ? 'recommendation changed' : refinement.outcome === 'RECOMMENDATION_WITHHELD' ? 'recommendation withheld' : refinement.outcome === 'EVIDENCE_EXPANDED' ? 'evidence expanded' : refinement.outcome === 'CANDIDATES_ADDED' ? 'candidates added' : 'no decision change'}</strong>
      <p>{refinementMessage(run, refinement)}</p>
      <details><summary>Search direction</summary><p><span>Reviewer feedback</span>{refinement.feedback}</p><p><span>Executed query</span>{refinement.query}</p></details>
    </article>,
  )}</div>;
}

export default function DecisionEvidence({
  run,
  candidateId = run.recommendedCandidateId ?? undefined,
}: {
  run: SourcingRun;
  candidateId?: string;
}) {
  const mandatory = run.requirements.filter(item => item.priority === 'MUST');
  const verifiedRequirements = mandatory.filter(item => item.status === 'VERIFIED').length;
  const recommended = run.candidates.find(item => item.id === run.recommendedCandidateId);
  const recommendedAssessment = run.assessments.find(
    item => item.candidateId === run.recommendedCandidateId,
  );
  const ranked = run.assessments
    .filter(item => isDatasetArtifact(run, item.candidateId))
    .sort(compareCandidateAssessments);
  const discoveryLeads = run.assessments
    .filter(item => !isDatasetArtifact(run, item.candidateId))
    .sort(compareCandidateAssessments);
  const excludedCandidateIds = new Set(run.excludedCandidateIds);
  const eligibleAlternatives = ranked.filter(item =>
    candidateIsEligibleForApproval(item, excludedCandidateIds));

  return <section className="decision-evidence" aria-labelledby="decision-evidence-title">
    <div className="decision-evidence-heading">
      <div>
        <p className="eyebrow">Human review</p>
        <h3 id="decision-evidence-title">Decision evidence</h3>
      </div>
      <span className="evidence-count">{run.evidence.length} total native records</span>
    </div>
    <RefinementResults run={run} />
    <p className="decision-outcome">
      {recommended && recommendedAssessment
        ? <><strong>Recommendation: {recommended.name}</strong> scored {recommendedAssessment.totalScore}/100 and passed every mandatory gate. Verify the linked evidence before approval.</>
        : eligibleAlternatives.length > 0
          ? <><strong>No agent recommendation.</strong> You may still approve one of the eligible shortlisted datasets.</>
          : <><strong>No eligible alternative is ready for approval.</strong> Continue refinement if another search remains.</>}
    </p>
    <dl className="decision-metrics">
      <div><dt>Mandatory requirements</dt><dd>{verifiedRequirements}/{mandatory.length} verified</dd></div>
      <div><dt>Datasets assessed</dt><dd>{ranked.length}</dd></div>
      <div><dt>Evidence confidence</dt><dd>{recommendedAssessment?.evidenceConfidence.toLowerCase() ?? 'not established'}</dd></div>
    </dl>

    <h4>Requirement coverage</h4>
    <div className="table-scroll">
      <table className="data-table evidence-table">
        <thead><tr><th>Requirement</th><th>Status</th><th>Native evidence</th></tr></thead>
        <tbody>{mandatory.map(requirement => <tr key={requirement.id}>
          <td><strong>{requirement.label}</strong>{requirement.expectedValues.length > 0 && <small>Expected: {requirement.expectedValues.join(', ')}</small>}</td>
          <td><span className={`evidence-status evidence-${requirement.status.toLowerCase()}`}>{requirement.status === 'VERIFIED' ? <Check size={12} aria-hidden="true" /> : <CircleX size={12} aria-hidden="true" />}{requirement.status.toLowerCase()}</span></td>
          <td><EvidenceLinks records={evidenceRecords(run, requirement.evidenceIds, candidateId)} /></td>
        </tr>)}</tbody>
      </table>
    </div>

    <h4>Dataset ranking</h4>
    <div className="table-scroll">
      <table className="data-table evidence-table">
        <thead><tr><th>Candidate</th><th>Score</th><th>Hard gates</th><th>Decision reason</th></tr></thead>
        <tbody>{ranked.length === 0 ? <tr><td colSpan={4}><span className="evidence-empty">No source was verified as a dataset artifact.</span></td></tr> : ranked.map(assessment => {
          const candidate = run.candidates.find(item => item.id === assessment.candidateId);
          const passed = assessment.gates.filter(gate => gate.passed).length;
          return <tr key={assessment.candidateId}>
            <td>{candidate ? <a href={candidate.canonicalUrl} target="_blank" rel="noopener noreferrer">{candidate.name} <ArrowUpRight size={11} aria-hidden="true" /></a> : assessment.candidateId}</td>
            <td><strong>{assessment.totalScore}</strong>/100<small>{assessment.tier.toLowerCase()}</small></td>
            <td>{passed}/{assessment.gates.length}</td>
            <td>{decisionReason(run, assessment.candidateId)}</td>
          </tr>;
        })}</tbody>
      </table>
    </div>
    {discoveryLeads.length > 0 && <details className="discovery-leads">
      <summary>Discovery leads excluded ({discoveryLeads.length})</summary>
      <p>These pages may lead to useful sources, but their native content did not prove that they directly publish a dataset. They are never approval options.</p>
      <ul>{discoveryLeads.map(assessment => {
        const candidate = run.candidates.find(item => item.id === assessment.candidateId);
        return <li key={assessment.candidateId}>
          {candidate
            ? <a href={candidate.canonicalUrl} target="_blank" rel="noopener noreferrer">{candidate.name} <ArrowUpRight size={11} aria-hidden="true" /></a>
            : assessment.candidateId}
          <span>{discoveryLeadReason(run, assessment.candidateId)}</span>
        </li>;
      })}</ul>
    </details>}
  </section>;
}
