class GateResult(WireModel):
    gate: str = Field(min_length=1, max_length=80)
    passed: bool
    reason: str = Field(min_length=1, max_length=500)
    evidence_ids: list[str] = Field(default_factory=list)


class ScoreBreakdown(WireModel):
    task_fit: int = Field(ge=0, le=35)
    training_readiness: int = Field(ge=0, le=20)
    acquisition_integrity: int = Field(ge=0, le=15)
    provenance_documentation: int = Field(ge=0, le=10)
    integration_readiness: int = Field(ge=0, le=10)
    license_clarity: int = Field(ge=0, le=5)
    evidence_consistency: int = Field(ge=0, le=5)

    @property
    def total(self) -> int:
        return sum(self.model_dump().values())


class CandidateAssessment(WireModel):
    candidate_id: str
    gates: list[GateResult]
    score: ScoreBreakdown
    total_score: int = Field(ge=0, le=100)
    tier: CandidateTier
    evidence_confidence: ConfidenceLevel
    recommendation_confidence: ConfidenceLevel = ConfidenceLevel.LOW
    missing_requirement_ids: list[str] = Field(default_factory=list)
    conflicts: list[str] = Field(default_factory=list)

    @model_validator(mode="after")
    def total_matches_breakdown(self) -> CandidateAssessment:
        if self.total_score != self.score.total:
            raise ValueError("total_score must equal the score breakdown")
        if any(not gate.passed for gate in self.gates) and self.tier is not CandidateTier.REJECT:
            raise ValueError("a candidate with a failed hard gate must be rejected")
        return self


class ApprovalRequest(WireModel):
    decision: ApprovalDecision
    candidate_id: str | None = None
    note: str | None = Field(default=None, max_length=1_000)

    @model_validator(mode="after")
    def approved_candidate_is_required(self) -> ApprovalRequest:
        if self.decision is ApprovalDecision.APPROVE and not self.candidate_id:
            raise ValueError("candidateId is required when approving")
        if self.decision is ApprovalDecision.REJECT and not self.note:
            raise ValueError("note is required when rejecting for refinement")
        return self


class RefinementOutcome(WireModel):
    iteration: int = Field(ge=1, le=2)
    feedback: str = Field(min_length=1, max_length=1_000)
    query: str = Field(min_length=3, max_length=400)
    outcome: RefinementOutcomeStatus
    rejected_candidate_id: str | None = None
    previous_recommended_candidate_id: str | None = None
    recommended_candidate_id: str | None = None
    new_candidate_ids: list[str] = Field(default_factory=list)
    new_evidence_ids: list[str] = Field(default_factory=list)


class SourcingManifest(WireModel):
    run_id: str
    candidate_id: str
    name: str
    canonical_url: HttpUrl
    revision: str | None = None
    license_id: str
    labels: list[str]
    sample_rate_hz: float | None = None
    file_extensions: list[str]
    total_size_bytes: int | None = None
    evidence_ids: list[str]
    limitations: list[str]
    approved_at: datetime = Field(default_factory=lambda: datetime.now(UTC))


class SourcingRun(WireModel):
    run_id: str = Field(pattern=r"^[0-9a-f-]{36}$")
    status: RunStatus
    brief: str
    constraints: SourcingConstraints
    requirements: list[ResearchRequirement] = Field(default_factory=list)
        )
        hypotheses = [SearchHypothesis.model_validate(item) for item in state["hypotheses"]]
        hypotheses.append(hypothesis)
        temporary_state = dict(state)
        temporary_state["hypotheses"] = _json_list(hypotheses)
        previous_result_count = len(state["search_results"])
        update = self._perform_searches(temporary_state, [hypothesis])
        review_results = [
            SearchResult.model_validate(item)
            for item in update["search_results"][previous_result_count:]
        ]
        discovered = canonicalize_results(review_results, self.settings.candidate_limit)
        existing = [DatasetCandidate.model_validate(item) for item in state["candidates"]]
        verified_ids = {item["candidate_id"] for item in state["profiles"]}
        merged: list[DatasetCandidate] = []
        seen: set[str] = set()
        for candidate in [
            *[item for item in existing if item.id in verified_ids],
            *discovered,
            *existing,
        ]:
            if candidate.id not in seen:
                seen.add(candidate.id)
                merged.append(candidate)
            if len(merged) == self.settings.candidate_limit:
                break
        previous_candidate_ids = {item.id for item in existing}
        new_candidate_ids = [
            item.id for item in discovered if item.id not in previous_candidate_ids
        ]
        update["candidates"] = _json_list(merged)
        update["review_iterations_used"] = iteration
        update["pending_refinement"] = {
            "iteration": iteration,
            "feedback": state["review_feedback"][-1],
            "query": hypothesis.query,
            "rejected_candidate_id": state.get("review_rejected_candidate_id"),
            "previous_recommended_candidate_id": state.get("recommended_candidate_id"),
            "previous_evidence_ids": [item["id"] for item in state["evidence"]],
            "new_candidate_ids": new_candidate_ids,
        }
        return update

    @staticmethod
    def route_after_review_refinement(state: SourcingState) -> str:
        return "end" if state["status"] == RunStatus.NEEDS_INPUT.value else "continue"

    def manifest_generation(self, state: SourcingState) -> dict[str, Any]:
        candidate_id = state["approved_candidate_id"]
        profile = next(
            DatasetProfile.model_validate(item)
            for item in state["profiles"]
            if item.get("candidate_id") == candidate_id
        )
        assessment = next(
            CandidateAssessment.model_validate(item)
            for item in state["assessments"]
            if item.get("candidate_id") == candidate_id
        )
        evidence = [
            EvidenceRecord.model_validate(item)
            for item in state["evidence"]
            if item.get("candidate_id") == candidate_id
        ]
        limitations = [
            self._conflict_resolution(evidence, profile.candidate_id, claim)
            for claim in assessment.conflicts
        ]
        limitations.append(
            "Collision/contact observations are not evidence of internal mechanical faults."
        )
        manifest = SourcingManifest(
            run_id=state["run_id"],
            candidate_id=profile.candidate_id,
            name=profile.name,
            canonical_url=profile.canonical_url,
            revision=profile.revision,
            license_id=profile.license_id or "",
            labels=profile.labels,
            sample_rate_hz=profile.sample_rate_hz,
            file_extensions=profile.file_extensions,
            total_size_bytes=profile.total_size_bytes,
            evidence_ids=[item.id for item in evidence],
            limitations=limitations,
            approved_at=datetime.now(UTC),
        )
        return {
            "status": RunStatus.APPROVED.value,
            "manifest": manifest.model_dump(mode="json"),
        }
import { useEffect, useState } from 'react';
import { AlertTriangle, ArrowUpRight, Check, CircleX } from 'lucide-react';
import { candidateIsEligibleForApproval } from '../services';
import type { CandidateAssessment, DatasetCandidate, DatasetProfile, SourcingManifest, SourcingReview, SourcingRun } from '../services';
import DecisionEvidence from './DecisionEvidence';
import { friendlyRetrievalNote } from './retrievalNotes';

type Props = {
  run: SourcingRun;
  busy: string;
  onReview: (review: SourcingReview) => void;
  onUseSource: (url: string) => void;
};

function CandidateSummary({ candidate, profile, assessment, isRecommendation }: {
  candidate: DatasetCandidate;
  profile?: DatasetProfile;
  assessment: CandidateAssessment;
  isRecommendation: boolean;
}) {
  return <article className="scout-candidate">
    <div className="scout-candidate-heading">
      <div><p className="eyebrow">{isRecommendation ? 'Agent recommendation' : 'Selected for review'}</p><h3>{candidate.name}</h3></div>
      <span className={`score-badge tier-${assessment.tier.toLowerCase()}`}>{assessment.totalScore}/100 · {assessment.tier.toLowerCase()}</span>
    </div>
    <a href={candidate.canonicalUrl} target="_blank" rel="noopener noreferrer">Open canonical source <ArrowUpRight size={13} aria-hidden="true" /></a>
    <dl className="scout-facts">
      <div><dt>Licence</dt><dd>{profile?.licenseId ?? 'Not verified'}</dd></div>
      <div><dt>Sampling</dt><dd>{profile?.sampleRateHz ? `${profile.sampleRateHz.toLocaleString('en-US')} Hz` : 'Not documented'}</dd></div>
      <div><dt>Evidence confidence</dt><dd>{assessment.evidenceConfidence.toLowerCase()}</dd></div>
      <div><dt>Recommendation confidence</dt><dd>{assessment.recommendationConfidence.toLowerCase()}</dd></div>
    </dl>
    <div className="gate-list" aria-label="Hard gate results">{assessment.gates.map(gate => <div key={gate.gate} className={gate.passed ? 'gate-pass' : 'gate-fail'}>{gate.passed ? <Check size={13} /> : <CircleX size={13} />}<span><strong>{gate.gate.replaceAll('_', ' ')}</strong><small>{gate.reason}</small></span></div>)}</div>
    {assessment.conflicts.length > 0 && <div className="scout-warning"><AlertTriangle size={15} aria-hidden="true" /><div><strong>Conflicting evidence retained</strong>{assessment.conflicts.map(item => <p key={item}>{item}</p>)}</div></div>}
  </article>;
