        request: CreateSourcingRun,
    ) -> PlanningDraft:
        if request.requirements is None:
            return draft
        terms = [
            value
            for requirement in request.requirements
            for value in requirement.expected_values
        ]
        return draft.model_copy(
            update={"search_terms": _unique([*draft.search_terms, *terms])[:12]}
        )

    @staticmethod
    def _system_requirements() -> list[ResearchRequirement]:
        return [
            ResearchRequirement(
                id="req_provenance",
                label="Canonical provenance",
                description="A native, versioned source identifies the dataset.",
                priority=RequirementPriority.MUST,
                category=RequirementCategory.PROVENANCE,
                is_system_required=True,
            ),
            ResearchRequirement(
                id="req_time_series",
                label="Usable time-series files",
                description="Downloadable files contain machine-readable telemetry.",
                priority=RequirementPriority.MUST,
                category=RequirementCategory.MODALITY,
                is_system_required=True,
            ),
        ]

    def confirm_requirements(
        self,
        definitions: list[RequirementDefinition],
    ) -> list[ResearchRequirement]:
        system_requirements = self._system_requirements()
        fixed_categories = {RequirementCategory.PROVENANCE, RequirementCategory.MODALITY}
        fixed_ids = {item.id for item in system_requirements}
        configurable = [
            ResearchRequirement.model_validate(
                item.model_copy(update={"is_system_required": False}).model_dump()
            )
            for item in definitions
            if item.category not in fixed_categories and item.id not in fixed_ids
        ]
        return [*system_requirements, *configurable]

    def preview(self, request: RequirementPreviewRequest) -> RequirementsPreview:
        run_request = CreateSourcingRun(
            brief=request.brief,
            constraints=request.constraints,
        )
        generated = self.requirements(run_request)
        custom: list[ResearchRequirement] = []
        seen: set[str] = set()
        for raw in request.custom_requirements:
            text = " ".join(raw.split())
            if text.casefold() in seen:
                continue
            seen.add(text.casefold())
            digest = hashlib.sha256(text.casefold().encode()).hexdigest()[:12]
            custom.append(
                ResearchRequirement(
                    id=f"req_custom_{digest}",
                    label=text[:120],
                    description="Custom natural-language requirement verified from native sources.",
                    priority=RequirementPriority.MUST,
        RequirementCategory.ACQUISITION: "total_size_bytes",
    }
    if requirement.category is RequirementCategory.OTHER:
        return f"custom_requirement:{requirement.id}"
    return claim_by_category.get(requirement.category)


def requirement_is_met(requirement: ResearchRequirement, profile: DatasetProfile) -> bool:
    expected = {value.casefold() for value in requirement.expected_values}
    if requirement.category is RequirementCategory.DOMAIN:
        return bool(expected) and expected.issubset(
            {domain.casefold() for domain in profile.domains}
        )
    if requirement.category is RequirementCategory.TASK_LABELS:
        return bool(expected) and expected.issubset({label.casefold() for label in profile.labels})
    if requirement.category is RequirementCategory.SAMPLING_RATE:
        try:
            minimum = max(float(value) for value in requirement.expected_values)
        except (ValueError, TypeError):
            return profile.sample_rate_hz is not None
        return profile.sample_rate_hz is not None and profile.sample_rate_hz >= minimum
    if requirement.category is RequirementCategory.LICENSE:
        return bool(profile.license_id) and (
            not expected or profile.license_id.casefold() in expected
        )
    if requirement.category is RequirementCategory.PROVENANCE:
        return bool(profile.revision and profile.source_kinds)
    if requirement.category is RequirementCategory.SCHEMA:
        return profile.schema_documented
    if requirement.category is RequirementCategory.ACQUISITION:
        return profile.acquisition_feasible
    if requirement.category is RequirementCategory.MODALITY:
        return profile.has_time_series_files
    return False


