from __future__ import annotations

import html
import time
from datetime import UTC, datetime
from typing import Any, TypedDict

import httpx
from langgraph.graph import END, START, StateGraph
from langgraph.types import interrupt

from data_sourcing.adapters import (
    NativeVerifier,
    TavilySearchAdapter,
    candidate_from_source,
    canonicalize_results,
)
from data_sourcing.adapters.discovery import SearchAdapter, SourceUnavailable
from data_sourcing.config import Settings
from data_sourcing.models import (
    ApprovalDecision,
    ApprovalRequest,
    CandidateAssessment,
    CandidateTier,
    CreateSourcingRun,
    DatasetCandidate,
    DatasetProfile,
    EvidenceRecord,
    ExecutionMode,
    HypothesisStatus,
    RefinementOutcome,
    RefinementOutcomeStatus,
    RequirementCategory,
    RequirementDefinition,
    ResearchRequirement,
    RunStatus,
    SearchHypothesis,
    SearchResult,
    SourceRole,
    SourcingConstraints,
    SourcingManifest,
    VerificationStatus,
)
from data_sourcing.planning import (
    PlanningDraft,
  id: string;
  candidateId: string;
  requirementId: string | null;
  claimKey: string;
  observedValue: string;
  sourceUrl: string;
  sourceKind: 'ZENODO' | 'GITHUB' | 'HUGGING_FACE';
  status: 'VERIFIED' | 'MISSING' | 'CONFLICTING' | 'UNVERIFIED';
  precedence: number;
  retrievedAt: string;
  note: string | null;
};

export type SuitabilityLevel = 'HIGH' | 'MEDIUM' | 'LOW';
export type SuitabilityFactor = {
  kind: 'STRENGTH' | 'LIMITATION' | 'BLOCKER';
  label: string;
  explanation: string;
  evidenceIds: string[];
};

export type CandidateAssessment = {
  candidateId: string;
  gates: { gate: string; passed: boolean; reason: string; evidenceIds: string[] }[];
  score: {
    taskFit: number;
    trainingReadiness: number;
    acquisitionIntegrity: number;
    provenanceDocumentation: number;
    integrationReadiness: number;
    licenseClarity: number;
    evidenceConsistency: number;
  };
  totalScore: number;
  tier: 'RECOMMEND' | 'SHORTLIST' | 'REJECT';
  suitabilityLevel?: SuitabilityLevel | null;
  suitabilityFactors?: SuitabilityFactor[];
  evidenceConfidence: 'HIGH' | 'MEDIUM' | 'LOW';
  recommendationConfidence: 'HIGH' | 'MEDIUM' | 'LOW';
  missingRequirementIds: string[];
  conflicts: string[];
};

export function candidateSuitabilityLevel(candidate: CandidateAssessment): SuitabilityLevel {
  if (candidate.suitabilityLevel) return candidate.suitabilityLevel;
  return { RECOMMEND: 'HIGH', SHORTLIST: 'MEDIUM', REJECT: 'LOW' }[candidate.tier];
}

export function candidateSuitabilityFactors(candidate: CandidateAssessment): SuitabilityFactor[] {
  if (candidate.suitabilityFactors?.length) return candidate.suitabilityFactors;
  return candidate.gates.map(gate => ({
    kind: gate.passed ? 'STRENGTH' : 'BLOCKER',
    label: gate.gate.replaceAll('_', ' '),
    explanation: gate.reason,
    evidenceIds: gate.evidenceIds,
  }));
}

export type SourcingManifest = {
  runId: string;
  candidateId: string;
  name: string;
  canonicalUrl: string;
  revision: string | null;
  licenseId: string;
  labels: string[];
  sampleRateHz: number | null;
  fileExtensions: string[];
  totalSizeBytes: number | null;
  evidenceIds: string[];
  limitations: string[];
  approvedAt: string;
};

export type SourcingReview =
  | { decision: 'APPROVE'; candidateId: string; note?: string }
  evidence: EvidenceRecord[];
  assessments: CandidateAssessment[];
  recommendedCandidateId: string | null;
  approvedCandidateId: string | null;
  excludedCandidateIds: string[];
  reviewFeedback: string[];
  reviewIterationsUsed: number;
  feedbackAllowed?: boolean;
  refinementOutcomes: RefinementOutcome[];
  gapQueriesUsed: number;
  tavilyCreditsUsed: number;
  executionMode: 'LIVE' | 'CACHED' | 'PARTIAL';
  errors: string[];
  reportMarkdown: string;
  manifest: SourcingManifest | null;
  createdAt: string;
  updatedAt: string;
};

export function candidateIsEligibleForApproval(
  candidate: CandidateAssessment,
  excludedCandidateIds: ReadonlySet<string>,
) {
  return !excludedCandidateIds.has(candidate.candidateId)
    && candidate.totalScore >= 65
    && candidate.tier !== 'REJECT'
    && candidate.missingRequirementIds.length === 0
    && candidate.gates.every(gate => gate.passed);
}

export function compareCandidateAssessments(
  left: CandidateAssessment,
  right: CandidateAssessment,
) {
  const identityMismatch = (candidate: CandidateAssessment) =>
    candidate.gates.some(gate => gate.gate === 'dataset_identity' && !gate.passed);

